import{_ as o,o as a,c,a3 as d}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"Drawer 篇 - Drawer 常识","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/16-Drawer-篇-Drawer-常识.md","filePath":"books/chrome-devtools/16-Drawer-篇-Drawer-常识.md","lastUpdated":1794316978000}'),r={name:"books/chrome-devtools/16-Drawer-篇-Drawer-常识.md"};function t(s,e,i,l,p,n){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="drawer-篇-drawer-常识" tabindex="-1">Drawer 篇 - Drawer 常识 <a class="header-anchor" href="#drawer-篇-drawer-常识" aria-label="Permalink to &quot;Drawer 篇 - Drawer 常识&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>说到 <code>Drawer</code> 大部分的朋友可能都很陌生，那 <code>Drawer</code> 是个什么东西？ <code>Chrome DevTools</code> 有很多部分，被分为9个 <code>tab</code> (俗称选项卡) ( <code>Elements</code> ， <code>Console</code> ， <code>Sources</code> ， <code>Network</code> ， 等等...)</p><p>但是，那仅仅是它的一部分而已！有一组平行的选项卡，被隐藏在主窗口之下。这个组合被称为 <strong><code>Drawer</code></strong></p><h2 id="_1-如何打开-drawer" tabindex="-1">1. 如何打开 <code>Drawer</code> ? <a class="header-anchor" href="#_1-如何打开-drawer" aria-label="Permalink to &quot;1. 如何打开 `Drawer` ?&quot;">​</a></h2><p>当你在 <code>DevTools</code>（任何选项卡）中时，按 <code>[esc]</code> 来显示它，再次按 <code>[esc]</code> 隐藏它：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/20/167ca65dd246e55d~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>默认情况下，您会看到一个 <code>console</code> 选项卡。 与主面板的 <code>console</code> 完全相同。 这就是为什么主面板会显示除了 <code>console</code> 之外的每个主要标签（ <code>Elements</code> ，<code>Sources</code> ，<code>Network</code> ...）- 因为在主面板中显示 <code>console</code> 没有意义。</p><p>这样的 <code>console</code> 很方便，例如在 <code>Elements</code> 选项卡打开时，我们同时可以看到 <code>console</code> 面板。但是在 <code>Drawer</code> 中其实还隐藏了更多细节。</p><h2 id="_2-drawer-里面到底有什么" tabindex="-1">2. <code>Drawer</code> 里面到底有什么？ <a class="header-anchor" href="#_2-drawer-里面到底有什么" aria-label="Permalink to &quot;2. `Drawer` 里面到底有什么？&quot;">​</a></h2><p><code>Drawer</code> 里隐藏着许多其他功能，大多数时候你可能不需要用到它们，这也是它们为什么被隐藏起来的原因，然鹅，你可以直接选择你想展示在这里的功能。</p><p>点击主页面在 <code>Drawer</code>的 <code>console</code> 面板前面的 <code>⋮</code> 图标来打开完整选项列表。另外，你也可以打开之前我们提到的 <code>command Menu</code> ，然后输入 <code>Drawer</code> 来打开</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/20/167ca65dd36c5272~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>Okay，让我们再看一遍所有的选项：</p><ul><li><code>Animations</code></li><li><code>Changes</code></li><li><code>Console</code></li><li><code>Coverage</code></li><li><code>Network conditions</code></li><li><code>Performance monitor</code></li><li><code>Quick source</code></li><li><code>Remote devices</code></li><li><code>Rendering</code></li><li><code>Request blocking</code></li><li><code>Search</code></li><li><code>Sensors</code></li><li><code>What’s new</code></li></ul><h2 id="_3-控制传感器" tabindex="-1">3. 控制传感器 <a class="header-anchor" href="#_3-控制传感器" aria-label="Permalink to &quot;3. 控制传感器&quot;">​</a></h2><p>如果你正在你的应用中使用一些获取位置信息的 <code>API</code> 而且想要测试一下它，总不能开着车环绕世界吧，(其实也不是不行😉)。</p><p><code>Drawer</code> 里的 <code>Sensors(传感器)</code> 面板可以让你模拟特定的位置: 支持从预定义的位置中进行选择，添加自己的位置，或者手动键入纬度/经度。选定的值将被 <code>navigator.geolocation.watchPosition</code>（或 <code>.getCurrentPosition</code> ）报告。</p><p>如果你的 <code>App</code> 使用加速计，传感器面板也可以模拟你设备在3D空间中的位置！</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/20/167caa871b562a48~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_4-模拟网络状态" tabindex="-1">4 .模拟网络状态 <a class="header-anchor" href="#_4-模拟网络状态" aria-label="Permalink to &quot;4 .模拟网络状态&quot;">​</a></h2><p>就像伪造你的位置一样，你可以使用 <code>Drawer</code> 里的 <code>Network conditions</code> 面板模拟特定的网络行为：模拟互联网为典型的3G网络甚至离线！ 这通常用来了解页面资源的大小。或者测试应用的离线功能。 除此之外，<code>Network conditions</code> 面板还可以模拟特定的用户代理。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/20/167caa8723019208~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_5-拿到-source" tabindex="-1">5.拿到 <code>source</code> <a class="header-anchor" href="#_5-拿到-source" aria-label="Permalink to &quot;5.拿到 `source`&quot;">​</a></h2><p>与 <code>drawer console</code> 一样，当我要专注于 <code>Elements</code> 面板时，有时我也想看源代码，这时就可以在 <code>drawer</code> 中选择显示 <code>Source</code>。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/20/167caa8719c239ee~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>如你所见，或许没有 <code>“主”Source</code> 面板的花里胡哨的功能，没有 <code>call stack</code> 或者 <code>control</code> ( <code>pause</code>， <code>step over</code>， 等等)按钮。而且如果断点被触发，它也不会显示在 <code>drawer</code> 的 <code>Quick sources</code> 中，而是显示在主 <code>Source</code> 中。</p><p>但是对于 <code>快速查看代码</code> ，或者 <code>设置断点</code> 来说，它却是非常有用的技巧。</p><h2 id="_6-检查代码-coverage" tabindex="-1">6. 检查代码 coverage <a class="header-anchor" href="#_6-检查代码-coverage" aria-label="Permalink to &quot;6. 检查代码 coverage&quot;">​</a></h2><p>实际开发中，你的页面可能并不需要位于尾部的许多代码。也许那是来自外部库的一大块 <code>JavaScript</code> ，也许是被遗忘的选择器上的一些 <code>CSS</code> 规则，它们不再匹配任何东西。</p><p>使用 <code>coverage</code> 面板来获得关于冗余代码的摘要-细节信息。使用 <code>Drawer</code> 菜单或者 <code>Command</code> 菜单来打开它。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f829daebc168d~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p><code>DevTools</code> 的 <code>coverage</code> 工具可以跟踪当前加载的 <code>JS</code> 和 <code>CSS</code> 文件的 <code>哪些行正在被执行</code> ，并显示 <code>未使用字节的百分比</code> 。</p><p>它用 <code>绿色</code> 的线条标记 <code>运行</code> 和用 <code>红色</code> 的线条标记 <code>未运行</code> 。 举个例子：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f829dae8fa7fb~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_7-检查你修改的内容" tabindex="-1">7. 检查你修改的内容 <a class="header-anchor" href="#_7-检查你修改的内容" aria-label="Permalink to &quot;7. 检查你修改的内容&quot;">​</a></h2><p>通过浏览器进行设计和调整 <code>css</code> ：能够在代码执行的地方进行调试是方便又有趣的开发方式。 但在某些时候，你可能希望将 <code>已更改的内容</code> 与 <code>最初加载的样式表</code> 进行比较。</p><p>为此，可以使用 <code>DevTools&#39; Drawer</code> 中的更改工具。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f829dad411a58~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>它不仅会使用差异形式的变化（像 <code>Git</code> 这样的源控制工具一样）向你展示，同时还可以撤销它们。</p><p>举个例子：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f829dadf27e11~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',42)])])}const h=o(r,[["render",t]]);export{m as __pageData,h as default};
